CREATE TABLE IF NOT EXISTS worlds(id integer PRIMARY KEY, name text NOT NULL, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tribes(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),name text NOT NULL UNIQUE,tag text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',founder_id bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS players(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),user_id bigint UNIQUE REFERENCES users(id),name text NOT NULL UNIQUE,tribe_id bigint REFERENCES tribes(id),role text NOT NULL DEFAULT 'member',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS villages(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),player_id bigint REFERENCES players(id),x smallint NOT NULL,y smallint NOT NULL,name text NOT NULL,state jsonb NOT NULL,points integer NOT NULL DEFAULT 0,UNIQUE(world_id,x,y),CHECK ((state->'resources'->>'wood')::numeric>=0 AND (state->'resources'->>'clay')::numeric>=0 AND (state->'resources'->>'iron')::numeric>=0));
CREATE INDEX IF NOT EXISTS villages_owner ON villages(player_id);
CREATE INDEX IF NOT EXISTS villages_map ON villages(world_id,x,y);
CREATE TABLE IF NOT EXISTS scheduled_events(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),village_id bigint NOT NULL REFERENCES villages(id),due_at timestamptz NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','cancelled')),config_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),applied_at timestamptz);
CREATE INDEX IF NOT EXISTS events_due ON scheduled_events(world_id,due_at,id) WHERE status='pending';
CREATE INDEX IF NOT EXISTS events_village ON scheduled_events(village_id,due_at,id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS reports(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),player_id bigint NOT NULL REFERENCES players(id),kind text NOT NULL,subject text NOT NULL,payload jsonb NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reports_inbox ON reports(player_id,id DESC);
CREATE TABLE IF NOT EXISTS outbox(id bigserial PRIMARY KEY,player_id bigint NOT NULL REFERENCES players(id),type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(id) WHERE sent_at IS NULL;
CREATE TABLE IF NOT EXISTS idempotency_keys(player_id bigint NOT NULL REFERENCES players(id),key text NOT NULL,request text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(player_id,key));
CREATE TABLE IF NOT EXISTS refresh_sessions(token_hash text PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),sender_id bigint NOT NULL REFERENCES players(id),recipient_id bigint NOT NULL REFERENCES players(id),subject text NOT NULL,body text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forum_threads(id bigserial PRIMARY KEY,tribe_id bigint NOT NULL REFERENCES tribes(id),author_id bigint NOT NULL REFERENCES players(id),title text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forum_posts(id bigserial PRIMARY KEY,thread_id bigint NOT NULL REFERENCES forum_threads(id),author_id bigint NOT NULL REFERENCES players(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS diplomacy(tribe_a bigint NOT NULL REFERENCES tribes(id),tribe_b bigint NOT NULL REFERENCES tribes(id),status text NOT NULL CHECK(status IN ('ally','neutral','enemy')),PRIMARY KEY(tribe_a,tribe_b));
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,world_id integer NOT NULL REFERENCES worlds(id),actor bigint REFERENCES players(id),action text NOT NULL,entity bigint,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
